tasks = []


def add_task(tasks, title):
    task = {"id": len(tasks) + 1, "title": title, "done": False}
    tasks.append(task)
    return task

def split_command(line):
    parts = line.split()
    if not parts:
        return "", []
    return parts[0].lower(), parts[1:]

